# 1. Assume prompt injection is inevitable; do not try to make the agent safe, make the perimeter restrictive.
def execute_action(agent_id, raw_intent, untrusted_payload):
    # 2. Convert loose agent intent into an explicit, deterministic schema; drop free-form parameters.
    typed_action = enforce_strict_contract(raw_intent)

    # 3. Dynamic blast-radius containment: check structural invariants (e.g., budget delta <= 10%, audience <= 500) rather than semantic intent.
    if not blast_radius_guard.is_within_tolerances(agent_id, typed_action):
        return route_to_canary_or_hold(typed_action)

    # 4. Mint short-lived, single-purpose credentials tied to this specific action hash, not a persistent OAuth user.
    ephemeral_creds = token_broker.mint_least_privilege_scope(agent_id, typed_action, ttl_seconds=30)

    # 5. Because Martech lacks rollbacks, pre-register compensating actions (e.g. pause campaign) before dispatch.
    compensation_plan = define_compensating_action(typed_action)

    # 6. Proxy the write with cryptographic provenance attached to the downstream audit payload.
    return martech_gateway.dispatch(typed_action, ephemeral_creds, provenance_id=hash(untrusted_payload), on_failure=compensation_plan)
